class Solution:
    def minSwapsCouples(self, row: list[int]) -> int:
        pos = {val: i for i, val in enumerate(row)}
        swaps = 0
        for i in range(0, len(row), 2):
            partner = row[i] ^ 1
            if row[i + 1] != partner:
                j = pos[partner]
                row[i + 1], row[j] = row[j], row[i + 1]
                pos[row[j]] = j
                pos[row[i + 1]] = i + 1
                swaps += 1
        return swaps

